 94→
 95→
 96→// Full cognitive profile result
 97→USTRUCT(BlueprintType)
 98→struct FTranslatorsProfile
 99→{
100→    GENERATED_BODY()
101→
102→    UPROPERTY(BlueprintReadOnly)
103→    TArray<FTranslatorsTrait> Traits;
104→
105→    UPROPERTY(BlueprintReadOnly)
106→    TArray<FString> Insights;
107→
108→    UPROPERTY(BlueprintReadOnly)
