 532→// === USD NATIVE COMMUNICATION (v2.0.0) ===
 533→
 534→bool UBridgeComponent::ProcessBridgeStateUsda()
 535→{
 536→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 537→    FString Content;
 538→
 539→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 540→    {
 541→        return false;
 542→    }
 543→
 544→    // Parse sync_status variant
 545→    FString SyncStatus = ParseUsdaVariant(Content, TEXT("sync_status"));
 546→    FString MessageType = ParseUsdaVariant(Content, TEXT("message_type"));
 547→
 548→    if (bVerboseLogging)
 549→    {
 550→        BridgeLog(FString::Printf(TEXT("USD sync_status=%s, message_type=%s"), *SyncStatus, *MessageType));
 551→    }
 552→
 553→    // Route based on message type
 554→    if (MessageType == TEXT("ready"))
 555→    {
 556→        HandleUsdaReadyState(Content);
 557→    }
 558→    else if (MessageType == TEXT("question") && SyncStatus == TEXT("question_pending"))
 559→    {
 560→        HandleUsdaQuestionState(Content);
 561→    }
 562→    else if (MessageType == TEXT("transition"))
 563→    {
 564→        HandleUsdaTransitionState(Content);
 565→    }
 566→    else if (MessageType == TEXT("finale"))
 567→    {
 568→        HandleUsdaFinaleState(Content);
 569→    }
 570→
 571→    return true;
 572→}
