 575→FString UBridgeComponent::ParseUsdaVariant(const FString& Content, const FString& VariantSetName)
 576→{
 577→    // Parse variant selection from: variants = { string variantName = "value" }
 578→    FString Pattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *VariantSetName);
 579→    FRegexPattern RegexPattern(Pattern);
 580→    FRegexMatcher Matcher(RegexPattern, Content);
 581→
 582→    if (Matcher.FindNext())
