 590→FString UBridgeComponent::ParseUsdaAttribute(const FString& Content, const FString& PrimPath, const FString& AttrName)
 591→{
 592→    // Find the prim section and extract attribute value
 593→    // This is a simplified parser - handles basic string/int/float attributes
 594→
 595→    // First find the prim section
 596→    FString PrimPattern = FString::Printf(TEXT("def [^\"]*\"%s\"[^{]*\\{([^}]*)\\}"), *PrimPath);
 597→    FRegexPattern PrimRegex(PrimPattern);
 598→    FRegexMatcher PrimMatcher(PrimRegex, Content);
 599→
 600→    FString PrimContent;
 601→    if (PrimMatcher.FindNext())
 602→    {
 603→        PrimContent = PrimMatcher.GetCaptureGroup(1);
 604→    }
 605→    else
 606→    {
 607→        // Try finding nested prim
 608→        PrimContent = Content;
 609→    }
 610→
 611→    // Parse string attribute
 612→    FString StringPattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *AttrName);
 613→    FRegexPattern StringRegex(StringPattern);
 614→    FRegexMatcher StringMatcher(StringRegex, PrimContent);
 615→    if (StringMatcher.FindNext())
 616→    {
 617→        return StringMatcher.GetCaptureGroup(1);
 618→    }
 619→
 620→    // Parse int attribute
 621→    FString IntPattern = FString::Printf(TEXT("int %s = (-?\\d+)"), *AttrName);
 622→    FRegexPattern IntRegex(IntPattern);
 623→    FRegexMatcher IntMatcher(IntRegex, PrimContent);
 624→    if (IntMatcher.FindNext())
 625→    {
 626→        return IntMatcher.GetCaptureGroup(1);
 627→    }
 628→
 629→    // Parse float/double attribute
 630→    FString FloatPattern = FString::Printf(TEXT("(?:float|double) %s = ([\\d.]+)"), *AttrName);
 631→    FRegexPattern FloatRegex(FloatPattern);
 632→    FRegexMatcher FloatMatcher(FloatRegex, PrimContent);
 633→    if (FloatMatcher.FindNext())
 634→    {
 635→        return FloatMatcher.GetCaptureGroup(1);
 636→    }
 637→
 638→    return TEXT("");
 639→}
