 657→void UBridgeComponent::HandleUsdaQuestionState(const FString& Content)
 658→{
 659→    // Parse Message prim
 660→    CurrentQuestion = FTranslatorsQuestion();
 661→    CurrentQuestion.Index = FCString::Atoi(*ParseUsdaAttribute(Content, TEXT("Message"), TEXT("index")));
 662→    CurrentQuestion.Total = FCString::Atoi(*ParseUsdaAttribute(Content, TEXT("Message"), TEXT("total")));
 663→    CurrentQuestion.QuestionId = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("question_id"));
 664→    CurrentQuestion.Text = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("text"));
 665→    CurrentQuestion.Scene = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("scene"));
 666→
 667→    // Parse Options
 668→    for (int32 i = 0; i < 3; ++i)
 669→    {
 670→        FString OptionPrim = FString::Printf(TEXT("Option_%d"), i);
 671→        FString Label = ParseUsdaAttribute(Content, OptionPrim, TEXT("label"));
 672→        FString Direction = ParseUsdaAttribute(Content, OptionPrim, TEXT("direction"));
 673→
 674→        if (!Label.IsEmpty())
 675→        {
 676→            CurrentQuestion.OptionLabels.Add(Label);
 677→            CurrentQuestion.OptionDirections.Add(Direction);
 678→        }
 679→    }
 680→
 681→    // Assign depth label based on question index
 682→    CurrentQuestion.DepthLabel = GetDepthLabelForIndex(CurrentQuestion.Index);
 683→
 684→    BridgeLog(FString::Printf(TEXT("USD Question %d/%d [%s]: %s"),
 685→        CurrentQuestion.Index + 1, CurrentQuestion.Total, *CurrentQuestion.DepthLabel, *CurrentQuestion.QuestionId));
 686→
 687→    // Build JSON for backward-compatible delegate
 688→    CurrentStateJson = BuildQuestionJson();
 689→    OnQuestionReceived.Broadcast(CurrentStateJson);
 690→}
