 719→FString UBridgeComponent::BuildQuestionJson()
 720→{
 721→    // Build JSON representation for backward-compatible delegates
 722→    TSharedPtr<FJsonObject> JsonObj = MakeShared<FJsonObject>();
 723→    JsonObj->SetStringField(TEXT("type"), TEXT("question"));
 724→    JsonObj->SetNumberField(TEXT("index"), CurrentQuestion.Index);
 725→    JsonObj->SetNumberField(TEXT("total"), CurrentQuestion.Total);
 726→    JsonObj->SetStringField(TEXT("id"), CurrentQuestion.QuestionId);
 727→    JsonObj->SetStringField(TEXT("text"), CurrentQuestion.Text);
 728→    JsonObj->SetStringField(TEXT("scene"), CurrentQuestion.Scene);
 729→
 730→    TArray<TSharedPtr<FJsonValue>> OptionsArray;
 731→    for (int32 i = 0; i < CurrentQuestion.OptionLabels.Num(); ++i)
 732→    {
 733→        TSharedPtr<FJsonObject> OptionObj = MakeShared<FJsonObject>();
 734→        OptionObj->SetNumberField(TEXT("index"), i);
 735→        OptionObj->SetStringField(TEXT("label"), CurrentQuestion.OptionLabels[i]);
 736→        OptionObj->SetStringField(TEXT("direction"), CurrentQuestion.OptionDirections[i]);
 737→        OptionsArray.Add(MakeShared<FJsonValueObject>(OptionObj));
 738→    }
 739→    JsonObj->SetArrayField(TEXT("options"), OptionsArray);
 740→
 741→    FString OutputString;
 742→    TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&OutputString);
 743→    FJsonSerializer::Serialize(JsonObj.ToSharedRef(), Writer);
 744→    return OutputString;
