 748→void UBridgeComponent::SendAnswerUsda(const FString& QuestionId, int32 OptionIndex, float ResponseTimeMs)
 749→{
 750→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 751→    FString Content;
 752→
 753→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 754→    {
 755→        BridgeLog(TEXT("ERROR: Could not read bridge_state.usda for answer"));
 756→        // Fall back to JSON
 757→        SendAnswer(QuestionId, OptionIndex, ResponseTimeMs);
 758→        return;
 759→    }
 760→
 761→    FString Timestamp = FDateTime::UtcNow().ToIso8601();
 762→    FString SelectedLabel = (OptionIndex >= 0 && OptionIndex < CurrentQuestion.OptionLabels.Num())
 763→        ? CurrentQuestion.OptionLabels[OptionIndex] : TEXT("");
 764→    FString SelectedDirection = (OptionIndex >= 0 && OptionIndex < CurrentQuestion.OptionDirections.Num())
 765→        ? CurrentQuestion.OptionDirections[OptionIndex] : TEXT("");
 766→
 767→    // Update sync_status variant to "answer_received"
 768→    Content = UpdateUsdaVariant(Content, TEXT("sync_status"), TEXT("answer_received"));
 769→    Content = UpdateUsdaVariant(Content, TEXT("message_type"), TEXT("answer"));
 770→
 771→    // Update Answer prim attributes
 772→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("question_id"), QuestionId, true);
 773→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("option_index"), FString::FromInt(OptionIndex), false);
 774→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("response_time_ms"), FString::SanitizeFloat(ResponseTimeMs), false);
 775→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("selected_label"), SelectedLabel, true);
 776→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("selected_direction"), SelectedDirection, true);
 777→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("timestamp"), Timestamp, true);
 778→
 779→    // Update behavioral signals
 780→    UpdateBehavioralSignals(Content, ResponseTimeMs);
 781→
 782→    // Write back
 783→    int32 MaxRetries = 3;
 784→    for (int32 Retry = 0; Retry < MaxRetries; ++Retry)
 785→    {
 786→        if (FFileHelper::SaveStringToFile(Content, *FilePath))
 787→        {
 788→            BridgeLog(FString::Printf(TEXT("USD answer sent: %s = option %d (%.0fms)"),
 789→                *QuestionId, OptionIndex, ResponseTimeMs));
 790→            return;
 791→        }
 792→        FPlatformProcess::Sleep(0.1f);
 793→    }
 794→
 795→    BridgeLog(TEXT("ERROR: Failed to write USD answer, falling back to JSON"));
 796→    SendAnswer(QuestionId, OptionIndex, ResponseTimeMs);
 797→}
