 800→FString UBridgeComponent::UpdateUsdaVariant(const FString& Content, const FString& VariantSetName, const FString& NewValue)
 801→{
 802→    // Simple string replacement for variant - more reliable than regex
 803→    FString SearchPattern = FString::Printf(TEXT("string %s = \""), *VariantSetName);
 804→    int32 StartIdx = Content.Find(SearchPattern);
 805→    if (StartIdx == INDEX_NONE)
 806→    {
 807→        return Content;
 808→    }
 809→
 810→    StartIdx += SearchPattern.Len();
 811→    int32 EndIdx = Content.Find(TEXT("\""), ESearchCase::CaseSensitive, ESearchDir::FromStart, StartIdx);
 812→    if (EndIdx == INDEX_NONE)
 813→    {
 814→        return Content;
 815→    }
 816→
 817→    // Build new content
 818→    FString Result = Content.Left(StartIdx) + NewValue + Content.Mid(EndIdx);
 819→    return Result;
 820→}
