 822→
 823→FString UBridgeComponent::UpdateUsdaAttribute(const FString& Content, const FString& PrimName, const FString& AttrName, const FString& NewValue, bool bIsString)
 824→{
 825→    // Find attribute pattern and replace value
 826→    // For string: string attrName = "value"
 827→    // For numeric: int/float/double attrName = value
 828→
 829→    FString Result = Content;
 830→
 831→    if (bIsString)
 832→    {
 833→        // Find: string attrName = "..."
 834→        FString SearchPattern = FString::Printf(TEXT("string %s = \""), *AttrName);
 835→        int32 StartIdx = Result.Find(SearchPattern);
 836→        if (StartIdx != INDEX_NONE)
 837→        {
 838→            StartIdx += SearchPattern.Len();
 839→            int32 EndIdx = Result.Find(TEXT("\""), ESearchCase::CaseSensitive, ESearchDir::FromStart, StartIdx);
 840→            if (EndIdx != INDEX_NONE)
 841→            {
 842→                FString EscapedValue = NewValue.Replace(TEXT("\\"), TEXT("\\\\")).Replace(TEXT("\""), TEXT("\\\""));
 843→                Result = Result.Left(StartIdx) + EscapedValue + Result.Mid(EndIdx);
 844→            }
 845→        }
 846→    }
 847→    else
 848→    {
 849→        // Find numeric attributes: int/float/double attrName = value
 850→        TArray<FString> TypePrefixes = { TEXT("int"), TEXT("float"), TEXT("double"), TEXT("bool") };
 851→
 852→        for (const FString& TypePrefix : TypePrefixes)
 853→        {
 854→            FString SearchPattern = FString::Printf(TEXT("%s %s = "), *TypePrefix, *AttrName);
 855→            int32 StartIdx = Result.Find(SearchPattern);
 856→            if (StartIdx != INDEX_NONE)
 857→            {
 858→                StartIdx += SearchPattern.Len();
 859→                // Find end of value (newline or space or semicolon)
 860→                int32 EndIdx = StartIdx;
 861→                while (EndIdx < Result.Len())
 862→                {
 863→                    TCHAR C = Result[EndIdx];
 864→                    if (C == '\n' || C == '\r' || C == ';' || C == ' ' || C == '\t')
 865→                    {
 866→                        break;
 867→                    }
 868→                    EndIdx++;
 869→                }
 870→                Result = Result.Left(StartIdx) + NewValue + Result.Mid(EndIdx);
 871→                break;
 872→            }
 873→        }
 874→    }
 875→
 876→    return Result;
 877→}
