 880→void UBridgeComponent::UpdateBehavioralSignals(FString& Content, float ResponseTimeMs)
 881→{
 882→    // Deterministic behavioral signal routing.
 883→    // Fixed thresholds ensure same signals produce same expert selection.
 884→
 885→    // PHASE 1: DETECT - Collect signals
 886→    ResponseTimes.Add(ResponseTimeMs);
 887→
 888→    // Calculate average response time (FIXED algorithm - sum/count)
 889→    float TotalTime = 0.0f;
 890→    for (float Time : ResponseTimes)
 891→    {
 892→        TotalTime += Time;
 893→    }
 894→    float AvgResponseTime = ResponseTimes.Num() > 0 ? TotalTime / ResponseTimes.Num() : 0.0f;
 895→
 896→    // FIXED THRESHOLDS (batch-invariant - same across all sessions)
 897→    const float HESITATION_THRESHOLD_MS = 10000.0f;   // 10 seconds
 898→    const float RAPID_CLICK_THRESHOLD_MS = 500.0f;    // 0.5 seconds
 899→    const float DEPLETED_AVG_THRESHOLD_MS = 15000.0f; // 15 seconds average
 900→    const int32 HESITATION_COUNT_THRESHOLD = 2;
 901→    const int32 RAPID_CLICK_COUNT_THRESHOLD = 3;
 902→
 903→    // Detect hesitation
 904→    bool bLongHesitation = ResponseTimeMs > HESITATION_THRESHOLD_MS;
 905→    if (bLongHesitation)
 906→    {
 907→        HesitationCount++;
 908→    }
 909→
 910→    // Detect rapid clicking
 911→    bool bRapidClick = ResponseTimeMs < RAPID_CLICK_THRESHOLD_MS && ResponseTimes.Num() > 1;
 912→    if (bRapidClick)
 913→    {
 914→        RapidClickCount++;
 915→    }
 916→
 917→    // PHASE 2: CASCADE - ADHD_MoE FIXED PRIORITY ROUTING
 918→    // Priority: Validator(1) > Scaffolder(2) > Restorer(3) > Refocuser(4) > Celebrator(5) > Socratic(6) > Direct(7)
 919→    // First match wins - NEVER skip or reorder
 920→
 921→    FString DetectedState = TEXT("focused");
 922→    FString RecommendedExpert = TEXT("Direct");
 923→    FString BurnoutLevel = TEXT("GREEN");
 924→    FString MomentumPhase = TEXT("rolling");
 925→
 926→    // Priority 1: Validator - frustrated, RED burnout, caps, negative signals
 927→    if (RapidClickCount > RAPID_CLICK_COUNT_THRESHOLD)
 928→    {
 929→        DetectedState = TEXT("frustrated");
 930→        RecommendedExpert = TEXT("Validator");
 931→        BurnoutLevel = TEXT("RED");
 932→        MomentumPhase = TEXT("crashed");
 933→    }
 934→    // Priority 2: Scaffolder - overwhelmed, stuck, too_many signals
 935→    else if (bLongHesitation || HesitationCount > HESITATION_COUNT_THRESHOLD)
 936→    {
 937→        DetectedState = TEXT("stuck");
 938→        RecommendedExpert = TEXT("Scaffolder");
 939→        BurnoutLevel = TEXT("ORANGE");
 940→        MomentumPhase = TEXT("declining");
 941→    }
 942→    // Priority 3: Restorer - depleted, ORANGE burnout, post-crash
 943→    else if (AvgResponseTime > DEPLETED_AVG_THRESHOLD_MS)
 944→    {
 945→        DetectedState = TEXT("depleted");
 946→        RecommendedExpert = TEXT("Restorer");
 947→        BurnoutLevel = TEXT("ORANGE");
 948→        MomentumPhase = TEXT("crashed");
 949→    }
 950→    // Priority 4: Refocuser - distracted, tangent signals
 951→    else if (ResponseTimes.Num() > 3 && ResponseTimeMs > AvgResponseTime * 2.0f)
 952→    {
 953→        DetectedState = TEXT("distracted");
 954→        RecommendedExpert = TEXT("Refocuser");
 955→        BurnoutLevel = TEXT("YELLOW");
 956→        MomentumPhase = TEXT("declining");
 957→    }
 958→    // Priority 5: Celebrator - task_complete, milestone reached
 959→    else if (CurrentQuestion.Index == CurrentQuestion.Total - 1)
 960→    {
 961→        DetectedState = TEXT("completing");
 962→        RecommendedExpert = TEXT("Celebrator");
 963→        BurnoutLevel = TEXT("GREEN");
 964→        MomentumPhase = TEXT("peak");
 965→    }
 966→    // Priority 6: Socratic - exploring, high energy, "what if" signals
 967→    else if (ResponseTimes.Num() >= 2 && ResponseTimeMs > 3000.0f && ResponseTimeMs < 8000.0f)
 968→    {
 969→        DetectedState = TEXT("exploring");
 970→        RecommendedExpert = TEXT("Socratic");
 971→        BurnoutLevel = TEXT("GREEN");
 972→        MomentumPhase = TEXT("building");
 973→    }
 974→    // Priority 7: Direct - focused, hyperfocused, flow state (DEFAULT)
 975→    else
 976→    {
 977→        DetectedState = TEXT("focused");
 978→        RecommendedExpert = TEXT("Direct");
 979→        BurnoutLevel = TEXT("GREEN");
 980→        MomentumPhase = (ResponseTimes.Num() > 5) ? TEXT("rolling") : TEXT("building");
 981→    }
 982→
 983→    // PHASE 3: LOCK - Parameters locked for this response (no further changes)
 984→
 985→    // PHASE 4: EXECUTE - Update signals in USD content
 986→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("last_response_time_ms"), FString::SanitizeFloat(ResponseTimeMs), false);
 987→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("average_response_time_ms"), FString::SanitizeFloat(AvgResponseTime), false);
 988→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("hesitation_count"), FString::FromInt(HesitationCount), false);
 989→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("long_hesitation_detected"), bLongHesitation ? TEXT("true") : TEXT("false"), false);
 990→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("rapid_click_count"), FString::FromInt(RapidClickCount), false);
 991→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("detected_state"), DetectedState, true);
 992→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("recommended_expert"), RecommendedExpert, true);
 993→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("burnout_level"), BurnoutLevel, true);
 994→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("momentum_phase"), MomentumPhase, true);
 995→
 996→    // PHASE 5: UPDATE - Log routing decision for traceability
 997→    if (bVerboseLogging)
 998→    {
 999→        BridgeLog(FString::Printf(TEXT("[EXEC] State=%s Expert=%s Burnout=%s Momentum=%s"),
1000→            *DetectedState, *RecommendedExpert, *BurnoutLevel, *MomentumPhase));
1001→    }
1002→}
