1057→// === COGNITIVE PROFILE PARSING ===
1058→
1059→FTranslatorsProfile UBridgeComponent::ParseCognitiveProfile(const FString& UsdPath)
1060→{
1061→    FTranslatorsProfile Profile;
1062→
1063→    FString Content;
1064→    if (!FFileHelper::LoadFileToString(Content, *UsdPath))
1065→    {
1066→        BridgeLog(FString::Printf(TEXT("Could not read profile: %s"), *UsdPath));
1067→        return Profile;
1068→    }
1069→
1070→    BridgeLog(FString::Printf(TEXT("Parsing cognitive profile from: %s"), *UsdPath));
1071→
1072→    // Parse checksum
1073→    {
1074→        FRegexPattern Pattern(TEXT("string checksum = \"([^\"]*)\""));
1075→        FRegexMatcher Matcher(Pattern, Content);
1076→        if (Matcher.FindNext())
1077→        {
1078→            Profile.Checksum = Matcher.GetCaptureGroup(1);
1079→        }
1080→    }
1081→
1082→    // Parse anchor
1083→    {
1084→        FRegexPattern Pattern(TEXT("string anchor = \"([^\"]*)\""));
1085→        FRegexMatcher Matcher(Pattern, Content);
1086→        if (Matcher.FindNext())
1087→        {
1088→            Profile.Anchor = Matcher.GetCaptureGroup(1);
1089→        }
1090→    }
1091→
1092→    // Parse anchor from customData
1093→    {
1094→        FRegexPattern Pattern(TEXT("string translators_anchor = \"([^\"]*)\""));
1095→        FRegexMatcher Matcher(Pattern, Content);
1096→        if (Matcher.FindNext())
1097→        {
1098→            Profile.Anchor = Matcher.GetCaptureGroup(1);
