 102→
 103→    // Polling fallback for non-editor builds
 104→    if (bUsePolling)
 105→    {
 106→        PollTimer += DeltaTime;
 107→        if (PollTimer >= PollInterval)
 108→        {
 109→            PollTimer = 0.0f;
 110→
 111→            FString StateFilePath = GetBridgeFilePath(TEXT("state.json"));
 112→            IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
 113→
 114→            if (PlatformFile.FileExists(*StateFilePath))
 115→            {
 116→                FDateTime ModTime = PlatformFile.GetTimeStamp(*StateFilePath);
 117→                if (ModTime > LastStateFileTime)
 118→                {
 119→                    LastStateFileTime = ModTime;
 120→                    bStateChangePending = true;
 121→                    TimeSinceLastStateChange = 0.0f;
 122→                }
 123→            }
 124→        }
 125→    }
 126→
 127→    // Debounced state file processing
 128→    if (bStateChangePending)
 129→    {
 130→        TimeSinceLastStateChange += DeltaTime;
 131→        if (TimeSinceLastStateChange >= DebounceTime)
 132→        {
 133→            bStateChangePending = false;
 134→            ProcessStateFile();
 135→        }
 136→    }
 137→
 138→    // Debounced USD file processing
 139→    if (bUsdChangePending)
 140→    {
 141→        TimeSinceLastUsdChange += DeltaTime;
 142→        if (TimeSinceLastUsdChange >= DebounceTime)
 143→        {
 144→            bUsdChangePending = false;
 145→            OnUsdFileChanged();
 146→        }
 147→    }
