 193→    FString FilePath = GetBridgeFilePath(TEXT("state.json"));
 194→    FString Content;
 195→
 196→    BridgeLog(FString::Printf(TEXT("Attempting to read: %s"), *FilePath));
 197→
 198→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 199→    {
 200→        BridgeLog(FString::Printf(TEXT("FAILED to read: %s (exists: %d)"),
 201→            *FilePath, PlatformFile.FileExists(*FilePath) ? 1 : 0));
 202→        return;
 203→    }
 204→
 205→    // Parse JSON
 206→    TSharedPtr<FJsonObject> JsonObj;
 207→    TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(Content);
 208→
 209→    if (!FJsonSerializer::Deserialize(Reader, JsonObj) || !JsonObj.IsValid())
 210→    {
 211→        BridgeLog(TEXT("ERROR: Invalid JSON in state.json"));
 212→        return;
 213→    }
 214→
 215→    CurrentStateJson = Content;
 216→    bUsingUsdMode = false;
 217→
 218→    // Route by type
 219→    FString StateType;
 220→    if (JsonObj->TryGetStringField(TEXT("type"), StateType))
 221→    {
 222→        if (StateType == TEXT("ready"))
 223→        {
 224→            HandleReadyState(JsonObj);
 225→        }
 226→        else if (StateType == TEXT("question"))
 227→        {
 228→            HandleQuestionState(JsonObj);
 229→        }
 230→        else if (StateType == TEXT("transition"))
 231→        {
 232→            HandleTransitionState(JsonObj);
 233→        }
 234→        else if (StateType == TEXT("finale"))
 235→        {
 236→            HandleFinaleState(JsonObj);
 237→        }
 238→        else
 239→        {
 240→            BridgeLog(FString::Printf(TEXT("Unknown state type: %s"), *StateType));
 241→        }
 242→    }
 243→}
