 264→void UBridgeComponent::HandleQuestionState(const TSharedPtr<FJsonObject>& JsonObj)
 265→{
 266→    // Protocol nests question data under "question" key, but also support flat format
 267→    const TSharedPtr<FJsonObject>* QuestionObjPtr;
 268→    const TSharedPtr<FJsonObject>& QuestionData =
 269→        JsonObj->TryGetObjectField(TEXT("question"), QuestionObjPtr) ? *QuestionObjPtr : JsonObj;
 270→
 271→    // Parse into struct
 272→    CurrentQuestion = FTranslatorsQuestion();
 273→    CurrentQuestion.Index = QuestionData->GetIntegerField(TEXT("index"));
 274→    CurrentQuestion.Total = QuestionData->GetIntegerField(TEXT("total"));
 275→    CurrentQuestion.QuestionId = QuestionData->GetStringField(TEXT("id"));
 276→    CurrentQuestion.Text = QuestionData->GetStringField(TEXT("text"));
 277→    CurrentQuestion.Scene = QuestionData->GetStringField(TEXT("scene"));
 278→
 279→    // Parse options array
 280→    const TArray<TSharedPtr<FJsonValue>>* OptionsArray;
 281→    if (QuestionData->TryGetArrayField(TEXT("options"), OptionsArray))
 282→    {
 283→        for (const TSharedPtr<FJsonValue>& OptionVal : *OptionsArray)
 284→        {
 285→            const TSharedPtr<FJsonObject>& OptionObj = OptionVal->AsObject();
 286→            if (OptionObj.IsValid())
 287→            {
 288→                CurrentQuestion.OptionLabels.Add(OptionObj->GetStringField(TEXT("label")));
 289→                CurrentQuestion.OptionDirections.Add(OptionObj->GetStringField(TEXT("direction")));
 290→            }
 291→        }
 292→    }
 293→
 294→    // Assign depth label based on question index
 295→    CurrentQuestion.DepthLabel = GetDepthLabelForIndex(CurrentQuestion.Index);
 296→
 297→    BridgeLog(FString::Printf(TEXT("Question %d/%d [%s]: %s"),
 298→        CurrentQuestion.Index + 1, CurrentQuestion.Total, *CurrentQuestion.DepthLabel, *CurrentQuestion.QuestionId));
 299→
 300→    // Broadcast raw JSON for flexible handling
 301→    OnQuestionReceived.Broadcast(CurrentStateJson);
 302→}
