 415→void UBridgeComponent::WriteJsonToFile(const FString& Filename, const TSharedPtr<FJsonObject>& JsonObj)
 416→{
 417→    FString FilePath = GetBridgeFilePath(Filename);
 418→    FString OutputString;
 419→
 420→    TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&OutputString);
 421→    FJsonSerializer::Serialize(JsonObj.ToSharedRef(), Writer);
 422→
 423→    // Write with retry logic (file may be locked by Claude Code reading it)
 424→    int32 MaxRetries = 3;
 425→    for (int32 Retry = 0; Retry < MaxRetries; ++Retry)
 426→    {
 427→        if (FFileHelper::SaveStringToFile(OutputString, *FilePath))
 428→        {
 429→            return; // Success
 430→        }
 431→
 432→        if (Retry < MaxRetries - 1)
 433→        {
 434→            BridgeLog(FString::Printf(TEXT("Write failed, retry %d/%d..."), Retry + 1, MaxRetries));
 435→            FPlatformProcess::Sleep(0.1f);
 436→        }
 437→    }
 438→
 439→    BridgeLog(FString::Printf(TEXT("ERROR: Failed to write %s after %d retries"), *Filename, MaxRetries));
 440→}
