 466→bool UBridgeComponent::ProcessBridgeStateUsda()
 467→{
 468→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 469→    FString Content;
 470→
 471→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 472→    {
 473→        return false;
 474→    }
 475→
 476→    // Parse sync_status variant
 477→    FString SyncStatus = ParseUsdaVariant(Content, TEXT("sync_status"));
 478→    FString MessageType = ParseUsdaVariant(Content, TEXT("message_type"));
 479→
 480→    if (bVerboseLogging)
 481→    {
 482→        BridgeLog(FString::Printf(TEXT("USD sync_status=%s, message_type=%s"), *SyncStatus, *MessageType));
 483→    }
 484→
 485→    // Route based on message type
 486→    if (MessageType == TEXT("ready"))
 487→    {
 488→        HandleUsdaReadyState(Content);
 489→    }
 490→    else if (MessageType == TEXT("question") && SyncStatus == TEXT("question_pending"))
 491→    {
 492→        HandleUsdaQuestionState(Content);
 493→    }
 494→    else if (MessageType == TEXT("transition"))
 495→    {
 496→        HandleUsdaTransitionState(Content);
 497→    }
 498→    else if (MessageType == TEXT("finale"))
 499→    {
 500→        HandleUsdaFinaleState(Content);
 501→    }
 502→
 503→    return true;
 504→}
