 507→FString UBridgeComponent::ParseUsdaVariant(const FString& Content, const FString& VariantSetName)
 508→{
 509→    // Parse variant selection from: variants = { string variantName = "value" }
 510→    FString Pattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *VariantSetName);
 511→    FRegexPattern RegexPattern(Pattern);
 512→    FRegexMatcher Matcher(RegexPattern, Content);
 513→
 514→    if (Matcher.FindNext())
 515→    {
 516→        return Matcher.GetCaptureGroup(1);
 517→    }
 518→    return TEXT("");
 519→}
 520→
 521→
 522→FString UBridgeComponent::ParseUsdaAttribute(const FString& Content, const FString& PrimPath, const FString& AttrName)
 523→{
 524→    // Find the prim section and extract attribute value
 525→    // This is a simplified parser - handles basic string/int/float attributes
 526→
 527→    // First find the prim section
 528→    FString PrimPattern = FString::Printf(TEXT("def [^\"]*\"%s\"[^{]*\\{([^}]*)\\}"), *PrimPath);
 529→    FRegexPattern PrimRegex(PrimPattern);
 530→    FRegexMatcher PrimMatcher(PrimRegex, Content);
 531→
 532→    FString PrimContent;
 533→    if (PrimMatcher.FindNext())
 534→    {
 535→        PrimContent = PrimMatcher.GetCaptureGroup(1);
 536→    }
 537→    else
 538→    {
 539→        // Try finding nested prim
 540→        PrimContent = Content;
 541→    }
 542→
 543→    // Parse string attribute
 544→    FString StringPattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *AttrName);
 545→    FRegexPattern StringRegex(StringPattern);
 546→    FRegexMatcher StringMatcher(StringRegex, PrimContent);
 547→    if (StringMatcher.FindNext())
 548→    {
 549→        return StringMatcher.GetCaptureGroup(1);
 550→    }
 551→
 552→    // Parse int attribute
 553→    FString IntPattern = FString::Printf(TEXT("int %s = (-?\\d+)"), *AttrName);
 554→    FRegexPattern IntRegex(IntPattern);
 555→    FRegexMatcher IntMatcher(IntRegex, PrimContent);
 556→    if (IntMatcher.FindNext())
 557→    {
 558→        return IntMatcher.GetCaptureGroup(1);
 559→    }
 560→
 561→    // Parse float/double attribute
 562→    FString FloatPattern = FString::Printf(TEXT("(?:float|double) %s = ([\\d.]+)"), *AttrName);
 563→    FRegexPattern FloatRegex(FloatPattern);
 564→    FRegexMatcher FloatMatcher(FloatRegex, PrimContent);
 565→    if (FloatMatcher.FindNext())
 566→    {
 567→        return FloatMatcher.GetCaptureGroup(1);
 568→    }
 569→
 570→    return TEXT("");
 571→}
