 589→void UBridgeComponent::HandleUsdaQuestionState(const FString& Content)
 590→{
 591→    // Parse Message prim
 592→    CurrentQuestion = FTranslatorsQuestion();
 593→    CurrentQuestion.Index = FCString::Atoi(*ParseUsdaAttribute(Content, TEXT("Message"), TEXT("index")));
 594→    CurrentQuestion.Total = FCString::Atoi(*ParseUsdaAttribute(Content, TEXT("Message"), TEXT("total")));
 595→    CurrentQuestion.QuestionId = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("question_id"));
 596→    CurrentQuestion.Text = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("text"));
 597→    CurrentQuestion.Scene = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("scene"));
 598→
 599→    // Parse Options
 600→    for (int32 i = 0; i < 3; ++i)
 601→    {
 602→        FString OptionPrim = FString::Printf(TEXT("Option_%d"), i);
 603→        FString Label = ParseUsdaAttribute(Content, OptionPrim, TEXT("label"));
 604→        FString Direction = ParseUsdaAttribute(Content, OptionPrim, TEXT("direction"));
 605→
 606→        if (!Label.IsEmpty())
 607→        {
 608→            CurrentQuestion.OptionLabels.Add(Label);
 609→            CurrentQuestion.OptionDirections.Add(Direction);
 610→        }
 611→    }
 612→
 613→    // Assign depth label based on question index
 614→    CurrentQuestion.DepthLabel = GetDepthLabelForIndex(CurrentQuestion.Index);
 615→
 616→    BridgeLog(FString::Printf(TEXT("USD Question %d/%d [%s]: %s"),
 617→        CurrentQuestion.Index + 1, CurrentQuestion.Total, *CurrentQuestion.DepthLabel, *CurrentQuestion.QuestionId));
 618→
 619→    // Build JSON for backward-compatible delegate
 620→    CurrentStateJson = BuildQuestionJson();
 621→    OnQuestionReceived.Broadcast(CurrentStateJson);
 622→}
