 651→FString UBridgeComponent::BuildQuestionJson()
 652→{
 653→    // Build JSON representation for backward-compatible delegates
 654→    TSharedPtr<FJsonObject> JsonObj = MakeShared<FJsonObject>();
 655→    JsonObj->SetStringField(TEXT("type"), TEXT("question"));
 656→    JsonObj->SetNumberField(TEXT("index"), CurrentQuestion.Index);
 657→    JsonObj->SetNumberField(TEXT("total"), CurrentQuestion.Total);
 658→    JsonObj->SetStringField(TEXT("id"), CurrentQuestion.QuestionId);
 659→    JsonObj->SetStringField(TEXT("text"), CurrentQuestion.Text);
 660→    JsonObj->SetStringField(TEXT("scene"), CurrentQuestion.Scene);
 661→
 662→    TArray<TSharedPtr<FJsonValue>> OptionsArray;
 663→    for (int32 i = 0; i < CurrentQuestion.OptionLabels.Num(); ++i)
 664→    {
 665→        TSharedPtr<FJsonObject> OptionObj = MakeShared<FJsonObject>();
 666→        OptionObj->SetNumberField(TEXT("index"), i);
 667→        OptionObj->SetStringField(TEXT("label"), CurrentQuestion.OptionLabels[i]);
 668→        OptionObj->SetStringField(TEXT("direction"), CurrentQuestion.OptionDirections[i]);
 669→        OptionsArray.Add(MakeShared<FJsonValueObject>(OptionObj));
 670→    }
 671→    JsonObj->SetArrayField(TEXT("options"), OptionsArray);
 672→
 673→    FString OutputString;
 674→    TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&OutputString);
 675→    FJsonSerializer::Serialize(JsonObj.ToSharedRef(), Writer);
 676→    return OutputString;
