 680→void UBridgeComponent::SendAnswerUsda(const FString& QuestionId, int32 OptionIndex, float ResponseTimeMs)
 681→{
 682→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 683→    FString Content;
 684→
 685→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 686→    {
 687→        BridgeLog(TEXT("ERROR: Could not read bridge_state.usda for answer"));
 688→        // Fall back to JSON
 689→        SendAnswer(QuestionId, OptionIndex, ResponseTimeMs);
 690→        return;
 691→    }
 692→
 693→    FString Timestamp = FDateTime::UtcNow().ToIso8601();
 694→    FString SelectedLabel = (OptionIndex >= 0 && OptionIndex < CurrentQuestion.OptionLabels.Num())
 695→        ? CurrentQuestion.OptionLabels[OptionIndex] : TEXT("");
 696→    FString SelectedDirection = (OptionIndex >= 0 && OptionIndex < CurrentQuestion.OptionDirections.Num())
 697→        ? CurrentQuestion.OptionDirections[OptionIndex] : TEXT("");
 698→
 699→    // Update sync_status variant to "answer_received"
 700→    Content = UpdateUsdaVariant(Content, TEXT("sync_status"), TEXT("answer_received"));
 701→    Content = UpdateUsdaVariant(Content, TEXT("message_type"), TEXT("answer"));
 702→
 703→    // Update Answer prim attributes
 704→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("question_id"), QuestionId, true);
 705→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("option_index"), FString::FromInt(OptionIndex), false);
 706→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("response_time_ms"), FString::SanitizeFloat(ResponseTimeMs), false);
 707→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("selected_label"), SelectedLabel, true);
 708→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("selected_direction"), SelectedDirection, true);
 709→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("timestamp"), Timestamp, true);
 710→
 711→    // Update behavioral signals
 712→    UpdateBehavioralSignals(Content, ResponseTimeMs);
 713→
 714→    // Write back
 715→    int32 MaxRetries = 3;
 716→    for (int32 Retry = 0; Retry < MaxRetries; ++Retry)
 717→    {
 718→        if (FFileHelper::SaveStringToFile(Content, *FilePath))
 719→        {
 720→            BridgeLog(FString::Printf(TEXT("USD answer sent: %s = option %d (%.0fms)"),
 721→                *QuestionId, OptionIndex, ResponseTimeMs));
 722→            return;
 723→        }
 724→        FPlatformProcess::Sleep(0.1f);
 725→    }
 726→
 727→    BridgeLog(TEXT("ERROR: Failed to write USD answer, falling back to JSON"));
 728→    SendAnswer(QuestionId, OptionIndex, ResponseTimeMs);
 729→}
