 731→
 732→FString UBridgeComponent::UpdateUsdaVariant(const FString& Content, const FString& VariantSetName, const FString& NewValue)
 733→{
 734→    // Simple string replacement for variant - more reliable than regex
 735→    FString SearchPattern = FString::Printf(TEXT("string %s = \""), *VariantSetName);
 736→    int32 StartIdx = Content.Find(SearchPattern);
 737→    if (StartIdx == INDEX_NONE)
 738→    {
 739→        return Content;
 740→    }
 741→
 742→    StartIdx += SearchPattern.Len();
 743→    int32 EndIdx = Content.Find(TEXT("\""), ESearchCase::CaseSensitive, ESearchDir::FromStart, StartIdx);
 744→    if (EndIdx == INDEX_NONE)
 745→    {
 746→        return Content;
 747→    }
 748→
 749→    // Build new content
 750→    FString Result = Content.Left(StartIdx) + NewValue + Content.Mid(EndIdx);
 751→    return Result;
 752→}
 753→
 754→
 755→FString UBridgeComponent::UpdateUsdaAttribute(const FString& Content, const FString& PrimName, const FString& AttrName, const FString& NewValue, bool bIsString)
 756→{
 757→    // Find attribute pattern and replace value
 758→    // For string: string attrName = "value"
 759→    // For numeric: int/float/double attrName = value
 760→
 761→    FString Result = Content;
 762→
 763→    if (bIsString)
 764→    {
 765→        // Find: string attrName = "..."
 766→        FString SearchPattern = FString::Printf(TEXT("string %s = \""), *AttrName);
 767→        int32 StartIdx = Result.Find(SearchPattern);
 768→        if (StartIdx != INDEX_NONE)
 769→        {
 770→            StartIdx += SearchPattern.Len();
 771→            int32 EndIdx = Result.Find(TEXT("\""), ESearchCase::CaseSensitive, ESearchDir::FromStart, StartIdx);
 772→            if (EndIdx != INDEX_NONE)
 773→            {
 774→                FString EscapedValue = NewValue.Replace(TEXT("\\"), TEXT("\\\\")).Replace(TEXT("\""), TEXT("\\\""));
 775→                Result = Result.Left(StartIdx) + EscapedValue + Result.Mid(EndIdx);
 776→            }
 777→        }
 778→    }
 779→    else
 780→    {
 781→        // Find numeric attributes: int/float/double attrName = value
 782→        TArray<FString> TypePrefixes = { TEXT("int"), TEXT("float"), TEXT("double"), TEXT("bool") };
 783→
 784→        for (const FString& TypePrefix : TypePrefixes)
 785→        {
 786→            FString SearchPattern = FString::Printf(TEXT("%s %s = "), *TypePrefix, *AttrName);
 787→            int32 StartIdx = Result.Find(SearchPattern);
 788→            if (StartIdx != INDEX_NONE)
 789→            {
 790→                StartIdx += SearchPattern.Len();
 791→                // Find end of value (newline or space or semicolon)
 792→                int32 EndIdx = StartIdx;
 793→                while (EndIdx < Result.Len())
 794→                {
 795→                    TCHAR C = Result[EndIdx];
 796→                    if (C == '\n' || C == '\r' || C == ';' || C == ' ' || C == '\t')
 797→                    {
 798→                        break;
 799→                    }
 800→                    EndIdx++;
 801→                }
 802→                Result = Result.Left(StartIdx) + NewValue + Result.Mid(EndIdx);
 803→                break;
 804→            }
 805→        }
 806→    }
 807→
 808→    return Result;
 809→}
