 812→void UBridgeComponent::UpdateBehavioralSignals(FString& Content, float ResponseTimeMs)
 813→{
 814→    // Deterministic behavioral signal routing.
 815→    // Fixed thresholds ensure same signals produce same expert selection.
 816→
 817→    // PHASE 1: DETECT - Collect signals
 818→    ResponseTimes.Add(ResponseTimeMs);
 819→
 820→    // Calculate average response time (FIXED algorithm - sum/count)
 821→    float TotalTime = 0.0f;
 822→    for (float Time : ResponseTimes)
 823→    {
 824→        TotalTime += Time;
 825→    }
 826→    float AvgResponseTime = ResponseTimes.Num() > 0 ? TotalTime / ResponseTimes.Num() : 0.0f;
 827→
 828→    // FIXED THRESHOLDS (batch-invariant - same across all sessions)
 829→    const float HESITATION_THRESHOLD_MS = 10000.0f;   // 10 seconds
 830→    const float RAPID_CLICK_THRESHOLD_MS = 500.0f;    // 0.5 seconds
 831→    const float DEPLETED_AVG_THRESHOLD_MS = 15000.0f; // 15 seconds average
 832→    const int32 HESITATION_COUNT_THRESHOLD = 2;
 833→    const int32 RAPID_CLICK_COUNT_THRESHOLD = 3;
 834→
 835→    // Detect hesitation
 836→    bool bLongHesitation = ResponseTimeMs > HESITATION_THRESHOLD_MS;
 837→    if (bLongHesitation)
 838→    {
 839→        HesitationCount++;
 840→    }
 841→
 842→    // Detect rapid clicking
 843→    bool bRapidClick = ResponseTimeMs < RAPID_CLICK_THRESHOLD_MS && ResponseTimes.Num() > 1;
 844→    if (bRapidClick)
 845→    {
 846→        RapidClickCount++;
 847→    }
 848→
 849→    // PHASE 2: CASCADE - ADHD_MoE FIXED PRIORITY ROUTING
 850→    // Priority: Validator(1) > Scaffolder(2) > Restorer(3) > Refocuser(4) > Celebrator(5) > Socratic(6) > Direct(7)
 851→    // First match wins - NEVER skip or reorder
 852→
 853→    FString DetectedState = TEXT("focused");
 854→    FString RecommendedExpert = TEXT("Direct");
 855→    FString BurnoutLevel = TEXT("GREEN");
 856→    FString MomentumPhase = TEXT("rolling");
 857→
 858→    // Priority 1: Validator - frustrated, RED burnout, caps, negative signals
 859→    if (RapidClickCount > RAPID_CLICK_COUNT_THRESHOLD)
 860→    {
 861→        DetectedState = TEXT("frustrated");
 862→        RecommendedExpert = TEXT("Validator");
 863→        BurnoutLevel = TEXT("RED");
 864→        MomentumPhase = TEXT("crashed");
 865→    }
 866→    // Priority 2: Scaffolder - overwhelmed, stuck, too_many signals
 867→    else if (bLongHesitation || HesitationCount > HESITATION_COUNT_THRESHOLD)
 868→    {
 869→        DetectedState = TEXT("stuck");
 870→        RecommendedExpert = TEXT("Scaffolder");
 871→        BurnoutLevel = TEXT("ORANGE");
 872→        MomentumPhase = TEXT("declining");
 873→    }
 874→    // Priority 3: Restorer - depleted, ORANGE burnout, post-crash
 875→    else if (AvgResponseTime > DEPLETED_AVG_THRESHOLD_MS)
 876→    {
 877→        DetectedState = TEXT("depleted");
 878→        RecommendedExpert = TEXT("Restorer");
 879→        BurnoutLevel = TEXT("ORANGE");
 880→        MomentumPhase = TEXT("crashed");
 881→    }
 882→    // Priority 4: Refocuser - distracted, tangent signals
 883→    else if (ResponseTimes.Num() > 3 && ResponseTimeMs > AvgResponseTime * 2.0f)
 884→    {
 885→        DetectedState = TEXT("distracted");
 886→        RecommendedExpert = TEXT("Refocuser");
 887→        BurnoutLevel = TEXT("YELLOW");
 888→        MomentumPhase = TEXT("declining");
 889→    }
 890→    // Priority 5: Celebrator - task_complete, milestone reached
 891→    else if (CurrentQuestion.Index == CurrentQuestion.Total - 1)
 892→    {
 893→        DetectedState = TEXT("completing");
 894→        RecommendedExpert = TEXT("Celebrator");
 895→        BurnoutLevel = TEXT("GREEN");
 896→        MomentumPhase = TEXT("peak");
 897→    }
 898→    // Priority 6: Socratic - exploring, high energy, "what if" signals
 899→    else if (ResponseTimes.Num() >= 2 && ResponseTimeMs > 3000.0f && ResponseTimeMs < 8000.0f)
 900→    {
 901→        DetectedState = TEXT("exploring");
 902→        RecommendedExpert = TEXT("Socratic");
 903→        BurnoutLevel = TEXT("GREEN");
 904→        MomentumPhase = TEXT("building");
 905→    }
 906→    // Priority 7: Direct - focused, hyperfocused, flow state (DEFAULT)
 907→    else
 908→    {
 909→        DetectedState = TEXT("focused");
 910→        RecommendedExpert = TEXT("Direct");
 911→        BurnoutLevel = TEXT("GREEN");
 912→        MomentumPhase = (ResponseTimes.Num() > 5) ? TEXT("rolling") : TEXT("building");
 913→    }
 914→
 915→    // PHASE 3: LOCK - Parameters locked for this response (no further changes)
 916→
 917→    // PHASE 4: EXECUTE - Update signals in USD content
 918→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("last_response_time_ms"), FString::SanitizeFloat(ResponseTimeMs), false);
 919→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("average_response_time_ms"), FString::SanitizeFloat(AvgResponseTime), false);
 920→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("hesitation_count"), FString::FromInt(HesitationCount), false);
 921→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("long_hesitation_detected"), bLongHesitation ? TEXT("true") : TEXT("false"), false);
 922→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("rapid_click_count"), FString::FromInt(RapidClickCount), false);
 923→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("detected_state"), DetectedState, true);
 924→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("recommended_expert"), RecommendedExpert, true);
 925→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("burnout_level"), BurnoutLevel, true);
 926→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("momentum_phase"), MomentumPhase, true);
 927→
 928→    // PHASE 5: UPDATE - Log routing decision for traceability
 929→    if (bVerboseLogging)
 930→    {
 931→        BridgeLog(FString::Printf(TEXT("[EXEC] State=%s Expert=%s Burnout=%s Momentum=%s"),
 932→            *DetectedState, *RecommendedExpert, *BurnoutLevel, *MomentumPhase));
 933→    }
 934→}
