 989→// === COGNITIVE PROFILE PARSING ===
 990→
 991→FTranslatorsProfile UBridgeComponent::ParseCognitiveProfile(const FString& UsdPath)
 992→{
 993→    FTranslatorsProfile Profile;
 994→
 995→    FString Content;
 996→    if (!FFileHelper::LoadFileToString(Content, *UsdPath))
 997→    {
 998→        BridgeLog(FString::Printf(TEXT("Could not read profile: %s"), *UsdPath));
 999→        return Profile;
1000→    }
1001→
1002→    BridgeLog(FString::Printf(TEXT("Parsing cognitive profile from: %s"), *UsdPath));
1003→
1004→    // Parse checksum
1005→    {
1006→        FRegexPattern Pattern(TEXT("string checksum = \"([^\"]*)\""));
1007→        FRegexMatcher Matcher(Pattern, Content);
1008→        if (Matcher.FindNext())
1009→        {
1010→            Profile.Checksum = Matcher.GetCaptureGroup(1);
1011→        }
1012→    }
1013→
1014→    // Parse anchor
1015→    {
1016→        FRegexPattern Pattern(TEXT("string anchor = \"([^\"]*)\""));
1017→        FRegexMatcher Matcher(Pattern, Content);
1018→        if (Matcher.FindNext())
1019→        {
1020→            Profile.Anchor = Matcher.GetCaptureGroup(1);
1021→        }
1022→    }
1023→
1024→    // Parse anchor from customData
1025→    {
1026→        FRegexPattern Pattern(TEXT("string translators_anchor = \"([^\"]*)\""));
1027→        FRegexMatcher Matcher(Pattern, Content);
1028→        if (Matcher.FindNext())
1029→        {
1030→            Profile.Anchor = Matcher.GetCaptureGroup(1);
1031→        }
1032→    }
1033→
1034→    // Parse Profile dimensions (float cognitive_density = 0.5)
1035→    // and Traits labels (string load = "adaptive")
1036→    // Combine them into FTranslatorsTrait entries
1037→    TMap<FString, float> DimensionScores;
1038→    TMap<FString, FString> TraitLabels;
1039→
1040→    // Extract Profile section: float <name> = <value>
1041→    {
1042→        int32 ProfileStart = Content.Find(TEXT("def Xform \"Profile\""));
1043→        if (ProfileStart != INDEX_NONE)
1044→        {
1045→            int32 BlockStart = Content.Find(TEXT("{"), ESearchCase::CaseSensitive, ESearchDir::FromStart, ProfileStart);
1046→            if (BlockStart != INDEX_NONE)
1047→            {
1048→                int32 BraceDepth = 1;
1049→                int32 BlockEnd = BlockStart + 1;
1050→                while (BlockEnd < Content.Len() && BraceDepth > 0)
1051→                {
1052→                    if (Content[BlockEnd] == TEXT('{')) BraceDepth++;
1053→                    else if (Content[BlockEnd] == TEXT('}')) BraceDepth--;
1054→                    BlockEnd++;
1055→                }
1056→
1057→                FString ProfileBlock = Content.Mid(BlockStart, BlockEnd - BlockStart);
1058→                FRegexPattern Pattern(TEXT("float (\\w+) = ([\\d.]+)"));
1059→                FRegexMatcher Matcher(Pattern, ProfileBlock);
1060→                while (Matcher.FindNext())
1061→                {
1062→                    FString Name = Matcher.GetCaptureGroup(1);
1063→                    float Value = FCString::Atof(*Matcher.GetCaptureGroup(2));
1064→                    DimensionScores.Add(Name, Value);
1065→                }
1066→            }
1067→        }
1068→    }
1069→
1070→    // Extract Traits section: string <question_id> = "<trait_label>"
1071→    // These are inside def Xform "Traits" { ... }
1072→    {
1073→        // Find the Traits block
1074→        int32 TraitsStart = Content.Find(TEXT("def Xform \"Traits\""));
1075→        if (TraitsStart != INDEX_NONE)
1076→        {
1077→            // Find the closing brace for this block
1078→            int32 BlockStart = Content.Find(TEXT("{"), ESearchCase::CaseSensitive, ESearchDir::FromStart, TraitsStart);
1079→            if (BlockStart != INDEX_NONE)
1080→            {
1081→                int32 BraceDepth = 1;
1082→                int32 BlockEnd = BlockStart + 1;
1083→                while (BlockEnd < Content.Len() && BraceDepth > 0)
1084→                {
1085→                    if (Content[BlockEnd] == TEXT('{')) BraceDepth++;
1086→                    else if (Content[BlockEnd] == TEXT('}')) BraceDepth--;
1087→                    BlockEnd++;
1088→                }
1089→
1090→                FString TraitsBlock = Content.Mid(BlockStart, BlockEnd - BlockStart);
1091→                FRegexPattern Pattern(TEXT("string (\\w+) = \"([^\"]*)\""));
1092→                FRegexMatcher Matcher(Pattern, TraitsBlock);
1093→                while (Matcher.FindNext())
1094→                {
1095→                    TraitLabels.Add(Matcher.GetCaptureGroup(1), Matcher.GetCaptureGroup(2));
1096→                }
1097→            }
1098→        }
1099→    }
1100→
1101→    // Map between question IDs and dimension names
1102→    // Question IDs: load, pace, uncertainty, feedback, recovery, starting, completion, essence
1103→    // Dimension names: cognitive_density, processing_pace, uncertainty_tolerance, feedback_style,
1104→    //                  home_altitude, guidance_frequency, default_paradigm, tangent_tolerance
1105→    TMap<FString, FString> QuestionToDimension;
1106→    QuestionToDimension.Add(TEXT("load"), TEXT("cognitive_density"));
1107→    QuestionToDimension.Add(TEXT("pace"), TEXT("processing_pace"));
1108→    QuestionToDimension.Add(TEXT("uncertainty"), TEXT("uncertainty_tolerance"));
1109→    QuestionToDimension.Add(TEXT("feedback"), TEXT("feedback_style"));
1110→    QuestionToDimension.Add(TEXT("recovery"), TEXT("home_altitude"));
1111→    QuestionToDimension.Add(TEXT("starting"), TEXT("guidance_frequency"));
1112→    QuestionToDimension.Add(TEXT("completion"), TEXT("default_paradigm"));
1113→    QuestionToDimension.Add(TEXT("essence"), TEXT("tangent_tolerance"));
1114→
1115→    // Build traits from combined data
1116→    for (const auto& Pair : TraitLabels)
1117→    {
1118→        FTranslatorsTrait Trait;
1119→        Trait.Label = Pair.Value;
1120→
1121→        // Find matching dimension
1122→        FString* DimName = QuestionToDimension.Find(Pair.Key);
1123→        if (DimName)
1124→        {
1125→            Trait.Dimension = *DimName;
1126→            float* Score = DimensionScores.Find(*DimName);
1127→            Trait.Score = Score ? *Score : 0.5f;
1128→        }
1129→        else
1130→        {
1131→            Trait.Dimension = Pair.Key;
1132→            Trait.Score = 0.5f;
1133→        }
1134→
1135→        // Generate behavior description from score
1136→        if (Trait.Score >= 0.7f)
1137→        {
1138→            Trait.Behavior = FString::Printf(TEXT("Strong %s tendency"), *Trait.Label);
1139→        }
1140→        else if (Trait.Score <= 0.3f)
1141→        {
1142→            Trait.Behavior = FString::Printf(TEXT("Measured %s approach"), *Trait.Label);
1143→        }
1144→        else
1145→        {
1146→            Trait.Behavior = FString::Printf(TEXT("Balanced %s style"), *Trait.Label);
1147→        }
1148→
1149→        Profile.Traits.Add(Trait);
1150→    }
1151→
1152→    // Generate insights from the profile data
1153→    // (The USDA doesn't contain explicit insights, so derive them from scores)
1154→    for (const FTranslatorsTrait& Trait : Profile.Traits)
1155→    {
1156→        if (Trait.Score >= 0.7f)
1157→        {
1158→            Profile.Insights.Add(FString::Printf(TEXT("High %s (%s) suggests strong preference in this dimension"),
1159→                *Trait.Dimension.Replace(TEXT("_"), TEXT(" ")), *Trait.Label));
1160→        }
1161→        else if (Trait.Score <= 0.3f)
1162→        {
1163→            Profile.Insights.Add(FString::Printf(TEXT("Low %s (%s) indicates a focused approach here"),
1164→                *Trait.Dimension.Replace(TEXT("_"), TEXT(" ")), *Trait.Label));
1165→        }
1166→    }
1167→
1168→    BridgeLog(FString::Printf(TEXT("Parsed profile: %d traits, %d insights, checksum=%s"),
1169→        Profile.Traits.Num(), Profile.Insights.Num(), *Profile.Checksum));
1170→
1171→    return Profile;
1172→}
