 18→void UBridgeComponent::BeginPlay()
 19→{
 20→    Super::BeginPlay();
 21→
 22→    // Get the subsystem
 23→    UGameInstance* GI = GetWorld() ? GetWorld()->GetGameInstance() : nullptr;
 24→    if (GI)
 25→    {
 26→        BridgeSubsystem = GI->GetSubsystem<UTranslatorsBridgeSubsystem>();
 27→    }
 28→
 29→    if (!BridgeSubsystem)
 30→    {
 31→        UE_LOG(LogTemp, Error, TEXT("[BridgeComponent] Could not find UTranslatorsBridgeSubsystem — is the TranslatorsBridge plugin enabled?"));
 32→        return;
 33→    }
 34→
 35→    // Forward config overrides to subsystem
 36→    BridgeSubsystem->bVerboseLogging = bVerboseLogging;
 37→
 38→    // Bind subsystem delegates to our legacy delegates
 39→    BridgeSubsystem->OnBridgeReady.AddDynamic(this, &UBridgeComponent::OnSubsystemBridgeReady);
 40→    BridgeSubsystem->OnQuestionReady.AddDynamic(this, &UBridgeComponent::OnSubsystemQuestionReady);
