244→void UW_QuestionDisplay::CreateOptionButtons()
245→{
246→    ClearOptions();
247→
248→    if (!OptionsContainer)
249→    {
250→        UE_LOG(LogTranslatorsBridge, Warning, TEXT("[W_QuestionDisplay] No OptionsContainer"));
251→        return;
252→    }
253→
254→    TSubclassOf<UW_OptionButton> ButtonClass = OptionButtonClass;
255→    if (!ButtonClass)
256→    {
257→        ButtonClass = UW_OptionButton::StaticClass();
258→    }
259→
260→    const int32 NumOptions = CurrentQuestion.OptionLabels.Num();
261→    for (int32 i = 0; i < NumOptions; i++)
262→    {
263→        UW_OptionButton* NewButton = CreateWidget<UW_OptionButton>(this, ButtonClass);
264→        if (NewButton)
265→        {
266→            FText Label = FText::FromString(CurrentQuestion.OptionLabels[i]);
267→            FString Dir = CurrentQuestion.OptionDirections.IsValidIndex(i)
268→                ? CurrentQuestion.OptionDirections[i]
269→                : TEXT("forward");
270→
271→            NewButton->SetupOption(i, Label, Dir);
272→            NewButton->OnOptionClicked.AddDynamic(this, &UW_QuestionDisplay::HandleOptionClicked);
273→
274→            UVerticalBoxSlot* ButtonSlot = OptionsContainer->AddChildToVerticalBox(NewButton);
275→            if (ButtonSlot)
276→            {
277→                ButtonSlot->SetPadding(FMargin(0.0f, 8.0f, 0.0f, 8.0f));
278→                ButtonSlot->SetHorizontalAlignment(HAlign_Fill);
279→            }
280→
281→            OptionButtons.Add(NewButton);
282→        }
283→    }
284→}
