287→void UW_QuestionDisplay::HandleOptionClicked(int32 OptionIndex)
288→{
289→    if (SelectedOptionIndex != -1)
290→    {
291→        return;
292→    }
293→
294→    SelectedOptionIndex = OptionIndex;
295→
296→    for (int32 i = 0; i < OptionButtons.Num(); i++)
297→    {
298→        if (OptionButtons[i])
299→        {
300→            OptionButtons[i]->SetHighlighted(i == OptionIndex);
301→        }
302→    }
303→
304→    UE_LOG(LogTranslatorsBridge, Log, TEXT("[W_QuestionDisplay] Answer: option %d"), OptionIndex);
305→    OnAnswerSelected.Broadcast(OptionIndex);
306→}
