 10→void UBridgeEditorSubsystem::Initialize(FSubsystemCollectionBase& Collection)
 11→{
 12→    Super::Initialize(Collection);
 13→    UE_LOG(LogTranslatorsBridge, Log, TEXT("BridgeEditorSubsystem initialized"));
 14→}
