 16→void UBridgeEditorSubsystem::Deinitialize()
 17→{
 18→    StopWatching();
 19→    StopBridgeProcess();
 20→
 21→    UE_LOG(LogTranslatorsBridge, Log, TEXT("BridgeEditorSubsystem deinitialized"));
 22→    Super::Deinitialize();
 23→}
 24→
 25→
 26→// === FILE WATCHING ===
 27→
 28→void UBridgeEditorSubsystem::StartWatching(const FString& BridgePath)
 29→{
 30→    if (bIsWatching)
 31→    {
 32→        if (WatchedPath == BridgePath)
 33→        {
 34→            return; // Already watching this path
 35→        }
 36→        StopWatching(); // Switch to new path
 37→    }
 38→
 39→    FDirectoryWatcherModule& DirWatcherModule =
 40→        FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
 41→    IDirectoryWatcher* DirWatcher = DirWatcherModule.Get();
 42→
 43→    if (!DirWatcher)
 44→    {
 45→        UE_LOG(LogTranslatorsBridge, Error, TEXT("Could not get DirectoryWatcher module"));
 46→        return;
 47→    }
 48→
 49→    IDirectoryWatcher::FDirectoryChanged Callback =
 50→        IDirectoryWatcher::FDirectoryChanged::CreateUObject(
 51→            this, &UBridgeEditorSubsystem::OnDirectoryChanged);
 52→
 53→    bool bSuccess = DirWatcher->RegisterDirectoryChangedCallback_Handle(
 54→        BridgePath, Callback, WatchHandle, 0);
 55→
 56→    if (bSuccess)
 57→    {
 58→        WatchedPath = BridgePath;
 59→        bIsWatching = true;
 60→        UE_LOG(LogTranslatorsBridge, Log, TEXT("Editor file watcher registered for: %s"), *BridgePath);
 61→    }
 62→    else
 63→    {
 64→        UE_LOG(LogTranslatorsBridge, Error, TEXT("Failed to register editor file watcher for: %s"), *BridgePath);
 65→    }
 66→}
 67→
 68→
 69→void UBridgeEditorSubsystem::StopWatching()
 70→{
 71→    if (!bIsWatching || !WatchHandle.IsValid())
 72→    {
 73→        return;
 74→    }
 75→
 76→    FDirectoryWatcherModule& DirWatcherModule =
 77→        FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
 78→    IDirectoryWatcher* DirWatcher = DirWatcherModule.Get();
 79→
 80→    if (DirWatcher)
 81→    {
 82→        DirWatcher->UnregisterDirectoryChangedCallback_Handle(WatchedPath, WatchHandle);
 83→        UE_LOG(LogTranslatorsBridge, Log, TEXT("Editor file watcher unregistered"));
 84→    }
 85→
 86→    bIsWatching = false;
 87→    WatchedPath.Empty();
 88→}
 89→
 90→
 91→void UBridgeEditorSubsystem::OnDirectoryChanged(const TArray<FFileChangeData>& Changes)
 92→{
 93→    for (const FFileChangeData& Change : Changes)
 94→    {
 95→        bool bIsUsdProfile = Change.Filename.EndsWith(TEXT("cognitive_profile.usda")) ||
 96→                             Change.Filename.EndsWith(TEXT("cognitive_substrate.usda"));
 97→
 98→        bool bIsBridgeState = Change.Filename.EndsWith(TEXT("state.json")) ||
 99→                              Change.Filename.EndsWith(TEXT("bridge_state.usda"));
100→
101→        if (bIsBridgeState || bIsUsdProfile)
102→        {
103→            // Broadcast to any listeners (BridgeComponents, editor tools, etc.)
104→            OnBridgeFileChanged.Broadcast(Change.Filename, bIsUsdProfile);
105→        }
106→    }
107→}
