  1→// W_TitleScreen.cpp
  2→// Implementation of title screen widget
  3→// Programmatic UI - no Blueprint required
  4→
  5→#include "W_TitleScreen.h"
  6→#include "TranslatorsBridgeRuntime.h"
  7→#include "Components/TextBlock.h"
  8→#include "Components/Border.h"
  9→#include "Components/VerticalBox.h"
 10→#include "Components/VerticalBoxSlot.h"
 11→#include "Components/Spacer.h"
 12→#include "Blueprint/WidgetTree.h"
 13→#include "Misc/Paths.h"
 14→
 15→namespace
 16→{
 17→    FSlateFontInfo MakeFont(int32 Size)
 18→    {
 19→        return FSlateFontInfo(FPaths::EngineContentDir() / TEXT("Slate/Fonts/Roboto-Regular.ttf"), Size);
 20→    }
 21→}
 22→
 23→
 24→UW_TitleScreen::UW_TitleScreen(const FObjectInitializer& ObjectInitializer)
 25→    : Super(ObjectInitializer)
 26→{
 27→    // Dark background matching the game aesthetic
 28→    BackgroundColor = FLinearColor(0.02f, 0.02f, 0.05f, 1.0f);
 29→    TitleColor = FLinearColor(0.36f, 1.0f, 0.86f, 1.0f);  // Cyan #5cffdb
 30→    SubtitleColor = FLinearColor(0.5f, 0.5f, 0.6f, 1.0f);
 31→    PromptColor = FLinearColor(0.36f, 1.0f, 0.86f, 0.8f);
 32→
 33→    // Widget must be focusable to receive key events
 34→    SetIsFocusable(true);
 35→}
 36→
 37→
 38→TSharedRef<SWidget> UW_TitleScreen::RebuildWidget()
 39→{
 40→    if (!TitleText)
 41→    {
 42→        BuildWidgetTree();
 43→    }
 44→    return Super::RebuildWidget();
 45→}
 46→
 47→
 48→void UW_TitleScreen::NativeConstruct()
 49→{
 50→    Super::NativeConstruct();
 51→
 52→    // Apply colors
 53→    if (BackgroundBorder)
 54→    {
 55→        BackgroundBorder->SetBrushColor(BackgroundColor);
 56→    }
 57→    if (TitleText)
 58→    {
 59→        TitleText->SetColorAndOpacity(FSlateColor(TitleColor));
 60→    }
 61→    if (SubtitleText)
 62→    {
 63→        SubtitleText->SetColorAndOpacity(FSlateColor(SubtitleColor));
 64→    }
 65→    if (PromptText)
 66→    {
 67→        PromptText->SetColorAndOpacity(FSlateColor(PromptColor));
 68→    }
 69→
 70→    // Request keyboard focus so we can receive Enter key
 71→    SetKeyboardFocus();
 72→
 73→    UE_LOG(LogTranslatorsBridge, Log, TEXT("[W_TitleScreen] Constructed (Programmatic UI)"));
 74→}
 75→
 76→
 77→void UW_TitleScreen::NativeTick(const FGeometry& MyGeometry, float InDeltaTime)
 78→{
 79→    Super::NativeTick(MyGeometry, InDeltaTime);
 80→
 81→    // Pulse the "Press ENTER to begin" text opacity
 82→    PulseTimer += InDeltaTime;
 83→    if (PromptText)
 84→    {
 85→        // Sine wave oscillation between 0.3 and 1.0
 86→        float Alpha = 0.3f + 0.7f * (0.5f + 0.5f * FMath::Sin(PulseTimer * 2.5f));
 87→        PromptText->SetRenderOpacity(Alpha);
 88→    }
 89→}
 90→
 91→
 92→FReply UW_TitleScreen::NativeOnKeyDown(const FGeometry& InGeometry, const FKeyEvent& InKeyEvent)
 93→{
 94→    if (!bStartRequested)
 95→    {
 96→        FKey Key = InKeyEvent.GetKey();
 97→        if (Key == EKeys::Enter || Key == EKeys::SpaceBar)
 98→        {
 99→            bStartRequested = true;
100→            UE_LOG(LogTranslatorsBridge, Log, TEXT("[W_TitleScreen] Start requested!"));
101→            OnStartRequested.Broadcast();
102→            return FReply::Handled();
103→        }
104→    }
105→
106→    return Super::NativeOnKeyDown(InGeometry, InKeyEvent);
107→}
108→
109→
110→void UW_TitleScreen::BuildWidgetTree()
111→{
112→    // Simple structure: Border (root, fills viewport) -> centered VerticalBox -> TextBlocks
113→    // Avoids CanvasPanel AutoSize issues that can collapse to zero
114→    BackgroundBorder = WidgetTree->ConstructWidget<UBorder>(UBorder::StaticClass(), TEXT("BackgroundBorder"));
115→    BackgroundBorder->SetBrushColor(BackgroundColor);
116→    BackgroundBorder->SetHorizontalAlignment(HAlign_Center);
117→    BackgroundBorder->SetVerticalAlignment(VAlign_Center);
118→    BackgroundBorder->SetPadding(FMargin(40.0f));
119→    WidgetTree->RootWidget = BackgroundBorder;
120→
121→    // Content box (centered by border alignment)
122→    UVerticalBox* ContentBox = WidgetTree->ConstructWidget<UVerticalBox>(UVerticalBox::StaticClass(), TEXT("ContentBox"));
123→    BackgroundBorder->AddChild(ContentBox);
124→
125→    // === Title: "The Translators" ===
126→    TitleText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("TitleText"));
127→    TitleText->SetText(NSLOCTEXT("TranslatorsBridge", "TitleScreen.Title", "The Translators"));
128→    TitleText->SetColorAndOpacity(FSlateColor(TitleColor));
129→    TitleText->SetJustification(ETextJustify::Center);
130→    TitleText->SetFont(MakeFont(56));
131→
132→    UVerticalBoxSlot* TitleSlot = ContentBox->AddChildToVerticalBox(TitleText);
133→    if (TitleSlot)
134→    {
135→        TitleSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 12.0f));
136→        TitleSlot->SetHorizontalAlignment(HAlign_Center);
137→    }
138→
139→    // === Subtitle: "A cognitive profiling experience" ===
140→    SubtitleText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("SubtitleText"));
141→    SubtitleText->SetText(NSLOCTEXT("TranslatorsBridge", "TitleScreen.Subtitle", "A cognitive profiling experience"));
142→    SubtitleText->SetColorAndOpacity(FSlateColor(SubtitleColor));
143→    SubtitleText->SetJustification(ETextJustify::Center);
144→    SubtitleText->SetFont(MakeFont(18));
145→
146→    UVerticalBoxSlot* SubtitleSlot = ContentBox->AddChildToVerticalBox(SubtitleText);
147→    if (SubtitleSlot)
148→    {
149→        SubtitleSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 60.0f));
150→        SubtitleSlot->SetHorizontalAlignment(HAlign_Center);
151→    }
152→
153→    // === Prompt: "Press ENTER to begin" ===
154→    PromptText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("PromptText"));
155→    PromptText->SetText(NSLOCTEXT("TranslatorsBridge", "TitleScreen.Prompt", "Press ENTER to begin"));
156→    PromptText->SetColorAndOpacity(FSlateColor(PromptColor));
157→    PromptText->SetJustification(ETextJustify::Center);
158→    PromptText->SetFont(MakeFont(16));
159→
160→    UVerticalBoxSlot* PromptSlot = ContentBox->AddChildToVerticalBox(PromptText);
161→    if (PromptSlot)
162→    {
163→        PromptSlot->SetHorizontalAlignment(HAlign_Center);
164→    }
165→
166→    UE_LOG(LogTranslatorsBridge, Log, TEXT("[W_TitleScreen] Built programmatic widget tree (Border root)"));
167→}
