164→void UW_QuestionDisplay::ShowQuestion(const FTranslatorsQuestion& Question)
165→{
166→    CurrentQuestion = Question;
167→    SelectedOptionIndex = -1;
168→
169→    // Update depth label with tier-specific color
170→    if (DepthText)
171→    {
172→        DepthText->SetText(FText::FromString(Question.DepthLabel));
173→
174→        // Color by tier
175→        FLinearColor TierColor;
176→        if (Question.DepthLabel == TEXT("SURFACE"))
177→        {
178→            TierColor = FLinearColor(0.5f, 0.8f, 0.5f, 1.0f);  // Sage green
179→        }
180→        else if (Question.DepthLabel == TEXT("PATTERNS"))
181→        {
182→            TierColor = FLinearColor(0.3f, 0.8f, 0.8f, 1.0f);  // Teal
183→        }
184→        else if (Question.DepthLabel == TEXT("FEELINGS"))
185→        {
186→            TierColor = FLinearColor(1.0f, 0.5f, 0.45f, 1.0f);  // Coral
187→        }
188→        else // CORE
189→        {
190→            TierColor = FLinearColor(1.0f, 0.85f, 0.3f, 1.0f);  // Gold
191→        }
192→        DepthText->SetColorAndOpacity(FSlateColor(TierColor));
193→    }
194→
195→    // Update question text
196→    if (QuestionText)
197→    {
198→        FString FormattedText = Question.Text.Replace(TEXT("\\n"), TEXT("\n"));
199→        QuestionText->SetText(FText::FromString(FormattedText));
200→    }
201→
202→    // Update progress
203→    UpdateProgress(Question.Index + 1, Question.Total);
204→
205→    // Create option buttons
206→    CreateOptionButtons();
207→
208→    UE_LOG(LogTranslatorsBridge, Log, TEXT("[W_QuestionDisplay] Showing question %d/%d: %s"),
209→        Question.Index + 1, Question.Total, *Question.QuestionId);
210→}
