 16→UW_ProgressIndicator::UW_ProgressIndicator(const FObjectInitializer& ObjectInitializer)
 17→    : Super(ObjectInitializer)
 18→{
 19→    TotalQuestions = 8;
 20→    CurrentQuestion = 0;
 21→
 22→    // 8-bit color scheme
 23→    CompletedColor = FLinearColor(0.36f, 1.0f, 0.86f, 1.0f);  // Cyan (#5cffdb)
 24→    IncompleteColor = FLinearColor(0.3f, 0.3f, 0.3f, 0.5f);   // Dim gray
 25→    CurrentColor = FLinearColor(1.0f, 0.8f, 0.2f, 1.0f);      // Gold
 26→}
