 28→
 29→void UW_ProgressIndicator::NativeConstruct()
 30→{
 31→    Super::NativeConstruct();
 32→
 33→    // Build widget tree programmatically if not bound from Blueprint
 34→    if (!IndicatorContainer)
 35→    {
 36→        BuildWidgetTree();
 37→    }
 38→
 39→    // Create indicator images if we have a container
 40→    if (IndicatorContainer)
 41→    {
 42→        IndicatorContainer->ClearChildren();
 43→        IndicatorImages.Empty();
 44→
 45→        for (int32 i = 0; i < TotalQuestions; i++)
 46→        {
 47→            UImage* Indicator = WidgetTree->ConstructWidget<UImage>(UImage::StaticClass());
 48→            if (Indicator)
 49→            {
 50→                // Set size (small square)
 51→                Indicator->SetDesiredSizeOverride(FVector2D(12.0f, 12.0f));
 52→
 53→                // Add to container
 54→                UHorizontalBoxSlot* IndicatorSlot = IndicatorContainer->AddChildToHorizontalBox(Indicator);
 55→                if (IndicatorSlot)
 56→                {
 57→                    IndicatorSlot->SetPadding(FMargin(4.0f, 0.0f, 4.0f, 0.0f));
 58→                    IndicatorSlot->SetVerticalAlignment(VAlign_Center);
 59→                }
 60→
 61→                IndicatorImages.Add(Indicator);
 62→            }
 63→        }
 64→    }
 65→
 66→    // Initial state
 67→    RefreshIndicators();
 68→
 69→    UE_LOG(LogTranslatorsBridge, Log, TEXT("[W_ProgressIndicator] Constructed with %d slots"), TotalQuestions);
 70→}
