 72→
 73→void UW_ProgressIndicator::UpdateProgress(int32 QuestionsCompleted)
 74→{
 75→    CurrentQuestion = FMath::Clamp(QuestionsCompleted, 0, TotalQuestions);
 76→    RefreshIndicators();
 77→
 78→    UE_LOG(LogTranslatorsBridge, Log, TEXT("[W_ProgressIndicator] Progress: %d/%d (%.0f%%)"),
 79→        CurrentQuestion, TotalQuestions, GetCompletionPercent() * 100.0f);
 80→}
