 82→
 83→void UW_ProgressIndicator::SetTotalQuestions(int32 Total)
 84→{
 85→    TotalQuestions = FMath::Max(1, Total);
 86→
 87→    // Rebuild indicators if needed
 88→    if (IndicatorImages.Num() != TotalQuestions && IndicatorContainer)
 89→    {
 90→        // Clear and rebuild
 91→        IndicatorContainer->ClearChildren();
 92→        IndicatorImages.Empty();
 93→
 94→        for (int32 i = 0; i < TotalQuestions; i++)
 95→        {
 96→            UImage* Indicator = WidgetTree->ConstructWidget<UImage>(UImage::StaticClass());
 97→            if (Indicator)
 98→            {
 99→                Indicator->SetDesiredSizeOverride(FVector2D(12.0f, 12.0f));
100→                UHorizontalBoxSlot* IndicatorSlot = IndicatorContainer->AddChildToHorizontalBox(Indicator);
101→                if (IndicatorSlot)
102→                {
103→                    IndicatorSlot->SetPadding(FMargin(4.0f, 0.0f, 4.0f, 0.0f));
104→                }
105→                IndicatorImages.Add(Indicator);
106→            }
107→        }
108→    }
109→
110→    RefreshIndicators();
111→}
112→
113→
114→float UW_ProgressIndicator::GetCompletionPercent() const
115→{
116→    if (TotalQuestions <= 0)
117→    {
118→        return 0.0f;
119→    }
120→    return static_cast<float>(CurrentQuestion) / static_cast<float>(TotalQuestions);
121→}
122→
123→
124→void UW_ProgressIndicator::RefreshIndicators()
125→{
126→    // Update indicator colors
127→    for (int32 i = 0; i < IndicatorImages.Num(); i++)
128→    {
129→        UImage* Indicator = IndicatorImages[i];
130→        if (!Indicator) continue;
131→
132→        FLinearColor Color;
133→        if (i < CurrentQuestion)
134→        {
135→            // Completed
136→            Color = CompletedColor;
137→        }
138→        else if (i == CurrentQuestion)
139→        {
140→            // Current (in progress)
141→            Color = CurrentColor;
142→        }
143→        else
144→        {
145→            // Not yet reached
146→            Color = IncompleteColor;
147→        }
148→
149→        Indicator->SetColorAndOpacity(Color);
150→    }
151→
152→    // Update text label
153→    if (ProgressLabel)
154→    {
155→        FString LabelText = FString::Printf(TEXT("%d / %d"), CurrentQuestion, TotalQuestions);
156→        ProgressLabel->SetText(FText::FromString(LabelText));
157→    }
158→}
