165→    WidgetTree->RootWidget = RootCanvas;
166→
167→    // Create horizontal container for indicators
168→    IndicatorContainer = WidgetTree->ConstructWidget<UHorizontalBox>(UHorizontalBox::StaticClass(), TEXT("IndicatorContainer"));
169→
170→    UCanvasPanelSlot* ContainerSlot = RootCanvas->AddChildToCanvas(IndicatorContainer);
171→    if (ContainerSlot)
172→    {
173→        ContainerSlot->SetAnchors(FAnchors(0.5f, 0.5f, 0.5f, 0.5f));
174→        ContainerSlot->SetAlignment(FVector2D(0.5f, 0.5f));
175→        ContainerSlot->SetAutoSize(true);
176→    }
177→
178→    UE_LOG(LogTranslatorsBridge, Log, TEXT("[W_ProgressIndicator] Built programmatic widget tree"));
179→}
