 733→
 734→FString UTranslatorsBridgeSubsystem::BuildQuestionJson()
 735→{
 736→    TSharedPtr<FJsonObject> JsonObj = MakeShared<FJsonObject>();
 737→    JsonObj->SetStringField(TEXT("type"), TEXT("question"));
 738→    JsonObj->SetNumberField(TEXT("index"), CurrentQuestion.Index);
 739→    JsonObj->SetNumberField(TEXT("total"), CurrentQuestion.Total);
 740→    JsonObj->SetStringField(TEXT("id"), CurrentQuestion.QuestionId);
 741→    JsonObj->SetStringField(TEXT("text"), CurrentQuestion.Text);
 742→    JsonObj->SetStringField(TEXT("scene"), CurrentQuestion.Scene);
 743→
 744→    TArray<TSharedPtr<FJsonValue>> OptionsArray;
 745→    for (int32 i = 0; i < CurrentQuestion.OptionLabels.Num(); ++i)
 746→    {
 747→        TSharedPtr<FJsonObject> OptionObj = MakeShared<FJsonObject>();
 748→        OptionObj->SetNumberField(TEXT("index"), i);
 749→        OptionObj->SetStringField(TEXT("label"), CurrentQuestion.OptionLabels[i]);
 750→        OptionObj->SetStringField(TEXT("direction"), CurrentQuestion.OptionDirections[i]);
 751→        OptionsArray.Add(MakeShared<FJsonValueObject>(OptionObj));
 752→    }
 753→    JsonObj->SetArrayField(TEXT("options"), OptionsArray);
 754→
 755→    FString OutputString;
 756→    TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&OutputString);
 757→    FJsonSerializer::Serialize(JsonObj.ToSharedRef(), Writer);
 758→    return OutputString;
 759→}
